-- Director: cross-branch operational visibility, read-only extension; existing write policies unchanged.
CREATE POLICY director_read_all ON public.portal_credit_customers FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.portal_profiles p WHERE p.auth_user_id = (SELECT auth.uid()) AND p.role = 'director' AND p.is_active = true));
